command:
const ops = game.modules.get("dg-ops")?.api;
if (!ops) return ui.notifications.warn("Delta Green: Ops Automation isn't active.");
if (!game.user.isGM) return ui.notifications.warn("That one is for the Handler.");
const u = [...game.user.targets].map(t => t.actor).find(a => a?.type === "unnatural") ?? ops.selected().find(a => a.type === "unnatural");
if (!u) return ui.notifications.warn("Select or target the Unnatural creature.");
const s = u.system.sanity ?? {};
const agents = ops.selected().filter(a => a.type !== "unnatural");
ops.sanGroupCard(agents.length ? agents : ops.team(), { successLoss: s.successLoss ?? "0", failureLoss: s.failedLoss ?? "1D6", category: "unnatural", source: u.name });
